    review: { keyVocab: ['ba_seseo', 'ba_ceceo', 'ba_yeismo', 'ba_leismo', 'ba_voseo', 'ba_castellano', 'ba_bonDia', 'ba_seny'], grammar: ['distinción / seseo / ceceo; yeísmo; aspiration of s.', 'vosotros vs ustedes; voseo; accepted leísmo vs non-standard laísmo.', 'Spain vs Latin America vocabulary (móvil/celular, coche/carro…).', 'No es que + subj., sino que + ind.; no solo…, sino que además…', 'Debate moves: fair reformulation, concession, reductio, closing.', 'Colloquial: profe, finde, pa, cansao, en plan; literary: inversion, free indirect style.'], expressions: ['Si no le he entendido mal…', 'Le concedo que…; no obstante…', 'Lo que está en juego es…', '¡Anda ya!'], mistakes: ['Seseo is not «wrong»', 'La dije → Le dije', 'No es que no quiero → quiera', 'no solo… pero también → sino que además'] },
    exam: [
      { t: 'listen', say: 'Si no le he entendido mal, usted sostiene que el bilingüismo divide a la sociedad', o: ['If I haven’t misunderstood, you maintain that bilingualism divides society.', 'You didn’t understand bilingualism.', 'Society understands bilingualism.'], a: 0, skill: 'listening' },
      { t: 'listen', say: 'Ustedes vienen al vermut, ¿no? Que hoy ya comimos tarde', o: ['Are you all coming for vermouth? We already ate late today. (ustedes + indefinido: Canarian/LatAm usage)', 'Standard Madrid usage.', 'The speaker is refusing.'], a: 0, skill: 'listening' },
      { t: 'mc', q: '«casa» = «caza» pronounced /ˈkasa/ is…', o: ['seseo', 'ceceo', 'distinción'], a: 0, skill: 'listening' },
      { t: 'mc', q: 'Non-standard:', o: ['Le dije la verdad.', 'La dije la verdad.', 'Le vi ayer (a Juan).'], a: 1, skill: 'grammar' },
      { t: 'fill', q: 'No es que no ___ (tener, yo) tiempo, sino que no me apetece.', a: ['tenga'], skill: 'grammar' }, { t: 'fill', q: 'No solo llegó tarde, ___ que además no se disculpó.', a: ['sino'], skill: 'grammar' },
      { t: 'mc', q: 'Spain «coger el autobús» in Mexico is usually…', o: ['tomar el camión', 'coger la guagua', 'agarrar el colectivo'], a: 0, skill: 'vocab' },
      { t: 'read', text: 'Hay quien sostiene que el catalán y el castellano compiten en Barcelona. Llevado al extremo, ese argumento implicaría que cada palabra en una lengua es una derrota para la otra. Nada más lejos de la realidad: en la barra de cualquier bar se piden «un cafè amb llet» y «una caña» sin que nadie se sienta vencido. No es que el bilingüismo carezca de tensiones, sino que la vida cotidiana suele resolverlas con más seny que los discursos.', q: 'What does the author argue?', o: ['The languages are at war', 'Daily life handles bilingualism better than speeches', 'Catalan should replace Spanish'], a: 1, skill: 'reading' },
      { t: 'read', text: 'Hay quien sostiene que el catalán y el castellano compiten en Barcelona. Llevado al extremo, ese argumento implicaría que cada palabra en una lengua es una derrota para la otra. Nada más lejos de la realidad: en la barra de cualquier bar se piden «un cafè amb llet» y «una caña» sin que nadie se sienta vencido. No es que el bilingüismo carezca de tensiones, sino que la vida cotidiana suele resolverlas con más seny que los discursos.', q: 'Which debate move appears in «Llevado al extremo…»?', o: ['reductio (showing absurd consequences)', 'fair reformulation', 'closing'], a: 0, skill: 'reading' },
      { t: 'tr', en: 'It’s not that I disagree; it’s that your argument needs qualifying.', a: ['no es que no este de acuerdo, sino que su argumento necesita matices', 'no es que no esté de acuerdo, sino que tu argumento habría que matizarlo', 'no es que no esté de acuerdo, sino que tu argumento necesita matices', 'no es que no esté de acuerdo, sino que su argumento habría que matizarlo', 'no es que no esté de acuerdo, sino que tu argumento hay que matizarlo'], skill: 'writing' },
      { t: 'write', prompt: 'C2 essay (260–300 words): «¿Existe un español "correcto"?» Discuss regional variation, standard norms and respect, using at least 5 debate moves and examples from 3 regions.', sample: 'Si se pregunta a un madrileño, a un sevillano y a un bonaerense cuál es el español «correcto», es probable que obtengamos tres respuestas distintas… No es que no exista una norma, sino que… Le concedo al purista que… no obstante… En última instancia, lo que está en juego es…', minWords: 240, skill: 'writing', rubric: ['Argument & nuance', 'Variation examples', 'Debate moves', 'Style', 'Accuracy'] },
      { t: 'speak', prompt: 'With Montse: talk for 2 minutes about living between languages (Vietnamese, English, Spanish). Use reformulation, concession and one colloquial vs one formal expression consciously.', sample: 'En mi caso, en casa hablo vietnamita y en la universidad, inglés. No es que una lengua sea más importante, sino que cada una guarda una parte de mí. Le concedo que a veces es agotador; no obstante…', target: ['no es que', 'no obstante'], skill: 'speaking' }
    ],
